// import { GraphicApp } from '../index';
import { ACControllerInterface } from './lib/ACController';
import { MouseInteraction, MouseEventData } from './EventInteraction/MouseInteraction';
import { KeyboardInteraction, KeyboardEventData } from './EventInteraction/KeyboardInteraction';

import { ActiveCommandDrawingBlock } from './Core/ActiveCommandDrawingBlock';

import { CBCanvas } from './Core/CBCanvas';

import { CBlockRenderer } from './Core/CBlockRenderer';

export interface AppDrawingBlockInterface {
    // static app: AppDrawing;
    // graphicApp: GraphicApp;
    mouseInteraction: MouseInteraction;
    keyboardInteraction: KeyboardInteraction;
    activeCommandDrawingBlock: ActiveCommandDrawingBlock;

    MouseInteraction(m: MouseEventData): void;
    KeyboardInteraction(k: KeyboardEventData): void;
    Destroy(): void;
}

export class Solution implements ACControllerInterface, AppDrawingBlockInterface {
    static app: Solution;

    divHost: HTMLDivElement;
    // graphicApp: GraphicApp;
    mouseInteraction: MouseInteraction;
    keyboardInteraction: KeyboardInteraction;
    activeCommandDrawingBlock: ActiveCommandDrawingBlock;

    canvasDB: CBCanvas;
    cBlockRenderer: CBlockRenderer;
    // .................................................. this is the app instance
    static Init(id: string) {
        Solution.app = new Solution(id);
    }
    // .................................................. end the app instance

    constructor(id: string) {
        const div = document.getElementById(id);
        this.divHost = div as HTMLDivElement;
        // this.graphicApp = graphicApp;
        // this.graphicApp.appDrawingBlock = this;
        this.canvasDB = new CBCanvas(this);
        this.activeCommandDrawingBlock = new ActiveCommandDrawingBlock(this);
        // this.graphicApp.ACController.AddController(this);
        // console.log('done');

    }
    Render(ctx: CanvasRenderingContext2D) {
        this.cBlockRenderer.Render(ctx);
    }
    MouseInteraction(m: MouseEventData): void {
        this.activeCommandDrawingBlock.MouseEventControl(m);
    }
    KeyboardInteraction(k: KeyboardEventData): void {
        this.activeCommandDrawingBlock.KeyboardEventControl(k);
    }
    Destroy() {
        // this.graphicApp.ACController.RemoveController(this);
        
    }
    public destroy() {
        // window.removeEventListener('resize', this.resize);
        this.canvasDB.Destroy();
        try {
            while (this.divHost && this.divHost.lastElementChild) {
                const lastChild = this.divHost.lastElementChild as Node;
                this.divHost.removeChild(lastChild);
            }
        } catch (error) { }
    }
}